import { Component, effect, inject, signal } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { SgThemeService } from '../sg-theme';
import {
  NEUTRAL_RAMPS, HUE_RAMPS, SEMANTIC_GROUPS, STATUS_ROWS, TAG_ROWS,
  DATAVIZ_CATEGORICAL, DATAVIZ_SEQ, UTILITY_TOKENS, readCssVar,
  type TokenGroup, type RampRow,
} from '../sg-tokens';

/** Parse '#rgb' | '#rrggbb' | 'rgb()' | 'rgba()' → [r,g,b] (0-255), bỏ alpha. */
function parseRgb(v: string): [number, number, number] | null {
  v = v.trim();
  const m = v.match(/rgba?\(([^)]+)\)/i);
  if (m) {
    const p = m[1].split(/[ ,/]+/).filter(Boolean).map(Number);
    if (p.length >= 3 && p.every((n) => !isNaN(n))) return [p[0], p[1], p[2]];
    return null;
  }
  let h = v.replace('#', '');
  if (h.length === 3) h = h.split('').map((c) => c + c).join('');
  if (h.length === 6) {
    const n = parseInt(h, 16);
    if (!isNaN(n)) return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  }
  return null;
}
function relLum([r, g, b]: [number, number, number]): number {
  const f = (c: number) => { c /= 255; return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}
function contrast(fg: string, bg: string): number | null {
  const a = parseRgb(fg), b = parseRgb(bg);
  if (!a || !b) return null;
  const [l1, l2] = [relLum(a), relLum(b)].sort((x, y) => y - x);
  return (l1 + 0.05) / (l2 + 0.05);
}
function grade(v: number): 'AAA' | 'AA' | 'AA-L' | 'FAIL' {
  return v >= 7 ? 'AAA' : v >= 4.5 ? 'AA' : v >= 3 ? 'AA-L' : 'FAIL';
}

@Component({
  selector: 'sg-colors',
  imports: [TranslateModule, NgTemplateOutlet],
  template: `
    <h1 class="sg-h">{{ 'sg.nav.colors' | translate }}</h1>
    <p class="sg-desc">{{ 'sg.colors.desc' | translate }}</p>

    <!-- ============ TẦNG 1 · PALETTE GỐC ============ -->
    <div class="tier">
      <span class="tier-n">01</span>
      <div><div class="tier-h">Palette gốc — Primitive</div>
        <div class="tier-d">Thang màu thô 0→950. KHÔNG dùng trực tiếp trong component — chỉ để token semantic tham chiếu.</div></div>
    </div>
    <section class="sg-group">
      <h2 class="sg-group-h">Neutral ramp</h2>
      <p class="grp-note">Config đổi Slate ↔ Gray → cả hệ neutral đổi. 2 thang cùng bậc sáng nên contrast giữ nguyên.</p>
      @for (r of ramps; track r.name) {
        <div class="ramp">
          <div class="ramp-name">{{ r.name }}<small>{{ r.note }}</small></div>
          <div class="ramp-steps">
            @for (s of r.steps; track s.var) {
              <div class="ramp-step" [title]="s.var + ' · ' + resolved()[s.var]">
                <div class="ramp-chip" [style.background]="'var(' + s.var + ')'"></div>
                <div class="ramp-l">{{ s.label }}</div>
              </div>
            }
          </div>
        </div>
      }
    </section>

    <section class="sg-group">
      <h2 class="sg-group-h">Accent / Status ramps</h2>
      <p class="grp-note">9 hue trạng thái, mỗi hue thang đầy đủ 50→950. Semantic status phân bổ: <b>base=600 · text=800 · border=200 · bg=50</b> (dark: text=300). Nhãn phải = status dùng hue đó.</p>
      @for (r of hueRamps; track r.name) {
        <div class="ramp">
          <div class="ramp-name">{{ r.name }}<small>{{ r.note }}</small></div>
          <div class="ramp-steps">
            @for (s of r.steps; track s.var) {
              <div class="ramp-step" [title]="s.var + ' · ' + resolved()[s.var]">
                <div class="ramp-chip" [style.background]="'var(' + s.var + ')'"></div>
                <div class="ramp-l">{{ s.label }}</div>
              </div>
            }
          </div>
        </div>
      }
    </section>

    <!-- ============ TẦNG 2 · SEMANTIC ============ -->
    <div class="tier">
      <span class="tier-n">02</span>
      <div><div class="tier-h">Token ngữ nghĩa — Semantic</div>
        <div class="tier-d">Token theo VAI TRÒ, tự bám Light/Dark. Đây là thứ component dùng.</div></div>
    </div>

    @for (g of semanticGroups; track g.label) {
      <ng-container [ngTemplateOutlet]="cardGroup" [ngTemplateOutletContext]="{ $implicit: g }" />
    }

    <!-- Status — bộ vai trò -->
    <section class="sg-group">
      <h2 class="sg-group-h">Status — Trạng thái</h2>
      <p class="grp-note">5 trạng thái × 5 vai trò. <b>On</b> = chữ trên nút solid (warning/away = tối vì nền sáng). Badge = contrast chữ trên nền surface.</p>
      @for (row of statusRows; track row.name) {
        <ng-container [ngTemplateOutlet]="roleRow" [ngTemplateOutletContext]="{ $implicit: row }" />
      }
    </section>

    <!-- Categorical / Tag — bộ vai trò -->
    <section class="sg-group">
      <h2 class="sg-group-h">Categorical — Nhãn / Chart / Lịch</h2>
      <p class="grp-note">10 hue phân loại (CÓ legend). Component Tag dùng bảng này. Nền/Viền = alpha bám nền; Chữ tự đảo theo theme (đều AAA).</p>
      @for (row of tagRows; track row.name) {
        <ng-container [ngTemplateOutlet]="roleRow" [ngTemplateOutletContext]="{ $implicit: row }" />
      }
    </section>

    <!-- Data-viz -->
    <section class="sg-group">
      <h2 class="sg-group-h">Data-viz — Biểu đồ</h2>
      <p class="grp-note">Categorical = thứ tự cố định chống trùng series. Sequential = thang 5 bậc cho heatmap/mật độ.</p>
      <div class="ramp">
        <div class="ramp-name">Categorical</div>
        <div class="ramp-steps">
          @for (s of datavizCat; track s.var) {
            <div class="ramp-step" [title]="s.var + ' · ' + resolved()[s.var]">
              <div class="ramp-chip" [style.background]="'var(' + s.var + ')'"></div>
              <div class="ramp-l">{{ s.label }}</div>
            </div>
          }
        </div>
      </div>
      @for (r of datavizSeq; track r.name) {
        <div class="ramp">
          <div class="ramp-name">{{ r.name }}</div>
          <div class="ramp-steps seq">
            @for (s of r.steps; track s.var) {
              <div class="ramp-step" [title]="s.var + ' · ' + resolved()[s.var]">
                <div class="ramp-chip" [style.background]="'var(' + s.var + ')'"></div>
                <div class="ramp-l">{{ s.label }}</div>
              </div>
            }
          </div>
        </div>
      }
    </section>

    <!-- Utility -->
    <ng-container [ngTemplateOutlet]="cardGroup" [ngTemplateOutletContext]="{ $implicit: utility }" />

    <!-- ===== reusable templates ===== -->
    <ng-template #cardGroup let-g>
      <section class="sg-group">
        <h2 class="sg-group-h">{{ g.label }}</h2>
        @if (g.note) { <p class="grp-note">{{ g.note }}</p> }
        <div class="sg-grid">
          @for (t of g.items; track t.var) {
            <div class="sg-card">
              <div class="swatch" [style.background]="'var(' + t.var + ')'"></div>
              <div class="sg-card-body">
                <div class="sg-card-label">{{ t.label }}</div>
                <div class="sg-card-val">{{ resolved()[t.var] }}</div>
                @if (g.contrastVs && cr()[t.var]) {
                  <span class="cr" [attr.data-g]="cr()[t.var]!.g">{{ cr()[t.var]!.v }} · {{ cr()[t.var]!.g }}</span>
                }
              </div>
            </div>
          }
        </div>
      </section>
    </ng-template>

    <ng-template #roleRow let-row>
      <div class="role-row">
        <div class="role-name">{{ row.name }}</div>
        <div class="role-sws">
          @for (sw of row.swatches; track sw.var) {
            <div class="role-sw" [title]="sw.var + ' · ' + resolved()[sw.var]">
              <div class="role-chip" [style.background]="'var(' + sw.var + ')'"></div>
              <div class="role-tag">{{ sw.role }}</div>
              @if (sw.contrast && cr()[sw.var]) {
                <span class="cr" [attr.data-g]="cr()[sw.var]!.g">{{ cr()[sw.var]!.g }}</span>
              }
            </div>
          }
        </div>
      </div>
    </ng-template>
  `,
  styleUrls: ['../sg-page.css'],
  styles: [`
    .swatch { height: 64px; border-bottom: 1px solid var(--border-sub); }
    .grp-note { margin: -4px 0 16px; color: var(--text-sub); font-size: var(--fs-13); max-width: 74ch; line-height: 1.5; }
    .grp-note b { color: var(--text-body); font-weight: 600; }

    /* Tier divider */
    .tier { display: flex; align-items: center; gap: 14px; margin: 40px 0 20px; padding-bottom: 14px; border-bottom: 2px solid var(--border-strong); }
    .tier:first-of-type { margin-top: 8px; }
    .tier-n { font-size: var(--fs-13); font-weight: 700; letter-spacing: 0.08em; color: var(--text-on-primary); background: var(--primary-base); border-radius: var(--radius-full); width: 34px; height: 34px; display: grid; place-items: center; flex: none; }
    .tier-h { font-size: var(--fs-18); font-weight: 600; color: var(--text-strong); }
    .tier-d { font-size: var(--fs-13); color: var(--text-sub); margin-top: 2px; max-width: 76ch; }

    /* Ramp strip */
    .ramp { display: flex; align-items: flex-start; gap: 16px; margin-bottom: 16px; flex-wrap: wrap; }
    .ramp-name { width: 92px; flex: none; font-size: var(--fs-13); font-weight: 600; color: var(--text-body); padding-top: 6px; }
    .ramp-name small { display: block; font-weight: 400; color: var(--text-soft); font-size: var(--fs-11); }
    .ramp-steps { display: flex; flex: 1; min-width: 280px; border-radius: var(--radius-md); overflow: hidden; box-shadow: inset 0 0 0 1px var(--border-sub); }
    .ramp-steps.seq { max-width: 420px; }
    .ramp-step { flex: 1; }
    .ramp-chip { height: 44px; }
    .ramp-l { font-size: var(--fs-10); text-align: center; color: var(--text-soft); padding: 3px 0; font-variant-numeric: tabular-nums; }

    /* Role cluster row */
    .role-row { display: flex; align-items: center; gap: 16px; padding: 10px 0; border-bottom: 1px solid var(--border-soft); flex-wrap: wrap; }
    .role-name { width: 168px; flex: none; font-size: var(--fs-13); font-weight: 600; color: var(--text-strong); text-transform: capitalize; }
    .role-sws { display: flex; gap: 10px; flex-wrap: wrap; }
    .role-sw { width: 76px; text-align: center; }
    .role-chip { height: 40px; border-radius: var(--radius-sm); box-shadow: inset 0 0 0 1px var(--border-sub); }
    .role-tag { font-size: var(--fs-11); color: var(--text-sub); margin-top: 4px; }

    /* Contrast badge */
    .cr {
      display: inline-block; margin-top: 3px; padding: 1px 6px; border-radius: var(--radius-full);
      font-size: var(--fs-10); font-weight: 700; font-variant-numeric: tabular-nums;
      background: var(--bg-surface-subtle); color: var(--text-sub);
    }
    .cr[data-g='AAA'], .cr[data-g='AA']  { background: var(--success-muted-light); color: var(--success-dark); }
    .cr[data-g='AA-L'] { background: var(--warning-muted-light); color: var(--warning-dark); }
    .cr[data-g='FAIL'] { background: var(--error-muted-light);   color: var(--error-dark); }
  `],
})
export class SgColors {
  protected readonly ramps = NEUTRAL_RAMPS;
  protected readonly hueRamps = HUE_RAMPS;
  protected readonly semanticGroups = SEMANTIC_GROUPS;
  protected readonly statusRows = STATUS_ROWS;
  protected readonly tagRows = TAG_ROWS;
  protected readonly datavizCat = DATAVIZ_CATEGORICAL;
  protected readonly datavizSeq = DATAVIZ_SEQ;
  protected readonly utility = UTILITY_TOKENS;

  private readonly theme = inject(SgThemeService);
  protected readonly resolved = signal<Record<string, string>>({});
  protected readonly cr = signal<Record<string, { v: string; g: string }>>({});

  constructor() {
    // Đọc lại resolve + tính contrast mỗi khi theme đổi (Light/Dark ra hex khác nhau).
    effect(() => {
      this.theme.theme();

      // Gom mọi var để resolve.
      const allVars = new Set<string>();
      const ramps: RampRow[] = [...NEUTRAL_RAMPS, ...HUE_RAMPS, ...DATAVIZ_SEQ];
      for (const r of ramps) for (const s of r.steps) allVars.add(s.var);
      for (const s of DATAVIZ_CATEGORICAL) allVars.add(s.var);
      const cardGroups: TokenGroup[] = [...SEMANTIC_GROUPS, UTILITY_TOKENS];
      for (const g of cardGroups) for (const t of g.items) allVars.add(t.var);
      for (const row of [...STATUS_ROWS, ...TAG_ROWS]) for (const sw of row.swatches) allVars.add(sw.var);
      allVars.add('--bg-surface');

      const map: Record<string, string> = {};
      for (const v of allVars) map[v] = readCssVar(v);
      this.resolved.set(map);

      // Contrast: card group có contrastVs → item vs bg đó; status/tag chữ → vs surface.
      const crMap: Record<string, { v: string; g: string }> = {};
      const put = (v: string, bg: string) => {
        const val = contrast(map[v], bg);
        if (val != null) crMap[v] = { v: val.toFixed(2), g: grade(val) };
      };
      for (const g of cardGroups) {
        if (!g.contrastVs) continue;
        const bg = map[g.contrastVs];
        for (const t of g.items) put(t.var, bg);
      }
      const surface = map['--bg-surface'];
      for (const row of [...STATUS_ROWS, ...TAG_ROWS]) for (const sw of row.swatches) if (sw.contrast) put(sw.var, surface);
      this.cr.set(crMap);
    });
  }
}
